-- SQL dump generated from pages/DOWNLOADS/barangay.json
-- Contains Philippine regions, provinces, cities/municipalities, and barangays
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `philippine_barangays`;
DROP TABLE IF EXISTS `philippine_cities`;
DROP TABLE IF EXISTS `philippine_provinces`;
DROP TABLE IF EXISTS `philippine_regions`;

CREATE TABLE `philippine_regions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_region_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `philippine_provinces` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `region_id` int unsigned NOT NULL,
  `name` varchar(191) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_province_per_region` (`region_id`,`name`),
  KEY `idx_province_region` (`region_id`),
  CONSTRAINT `fk_province_region` FOREIGN KEY (`region_id`) REFERENCES `philippine_regions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `philippine_cities` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `province_id` int unsigned NOT NULL,
  `name` varchar(191) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_city_per_province` (`province_id`,`name`),
  KEY `idx_city_province` (`province_id`),
  CONSTRAINT `fk_city_province` FOREIGN KEY (`province_id`) REFERENCES `philippine_provinces` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `philippine_barangays` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `city_id` int unsigned NOT NULL,
  `name` varchar(191) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_barangay_per_city` (`city_id`,`name`),
  KEY `idx_barangay_city` (`city_id`),
  CONSTRAINT `fk_barangay_city` FOREIGN KEY (`city_id`) REFERENCES `philippine_cities` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




















































































































































































































SET FOREIGN_KEY_CHECKS = 1;
